			connection.add(r2, RDF.TYPE, nodeType);
			connection.add(r1, edge, n1);
			connection.add(r1, edge, n2);
			connection.add(r2, edge, n2);
			connection.add(incoming, edge, r1);
			connection.add(r1, weight, vf.createLiteral(1));
			connection.add(r1, weight, vf.createLiteral(2));
			connection.add(n1, weight, vf.createLiteral(3));
			connection.add(n1, weight, vf.createLiteral(4));
			connection.add(n2, weight, vf.createLiteral(5));
			connection.add(incoming, weight, vf.createLiteral(6));

			String queryText = """
					PREFIX ex: <urn:factorized-union:>
					SELECT * WHERE {
					  { ?root a ex:Node . }
					  UNION
					  { ?root ex:edge ?unionNeighbor . }
					  OPTIONAL {
					    ?root ex:edge ?neighbor .
					    OPTIONAL { ?neighbor ex:weight ?neighborWeight . }
					  }
					  OPTIONAL {
					    ?root ex:weight ?weight .
					    BIND(?weight AS ?nodeWeight)
					  }
					  OPTIONAL {
					    { ?incoming ex:edge ?root . }
					    UNION
					    { ?root ex:edge ?incoming . }
					    OPTIONAL { ?incoming ex:weight ?incomingWeight . }
					  }
					  FILTER(?nodeWeight != 0 || !BOUND(?nodeWeight))
					}
					""";
			TupleQuery query = connection.prepareTupleQuery(queryText);
			TupleExpr tupleExpr = ((SailTupleQuery) query).getParsedQuery().getTupleExpr().clone();
