	@Test
	void existsAndNotExistsFiltersPreserveOuterBagMultiplicity() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		String namespace = "urn:factorized-exists:";
		IRI rootType = vf.createIRI(namespace, "Root");
		IRI candidate = vf.createIRI(namespace, "candidate");
		IRI blocked = vf.createIRI(namespace, "blocked");
		IRI repeat = vf.createIRI(namespace, "repeat");
		IRI r1 = vf.createIRI(namespace, "r1");
		IRI r2 = vf.createIRI(namespace, "r2");
		IRI a = vf.createIRI(namespace, "a");
		IRI b = vf.createIRI(namespace, "b");
		IRI c = vf.createIRI(namespace, "c");

		SailRepository repository = new SailRepository(new MemoryStore());
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(r1, RDF.TYPE, rootType);
			connection.add(r2, RDF.TYPE, rootType);
			connection.add(r1, candidate, a);
			connection.add(r1, candidate, b);
			connection.add(r2, candidate, c);
			connection.add(r1, blocked, a);
			connection.add(r1, repeat, vf.createIRI(namespace, "repeat-1"));
			connection.add(r1, repeat, vf.createIRI(namespace, "repeat-2"));
			connection.add(r2, repeat, vf.createIRI(namespace, "repeat-1"));
			connection.add(r2, repeat, vf.createIRI(namespace, "repeat-2"));

			for (String filter : List.of(
					"FILTER EXISTS { ?root ex:blocked ?candidate . }",
					"FILTER NOT EXISTS { ?root ex:blocked ?candidate . }",
					"FILTER(?candidate != ex:b && EXISTS { ?root ex:blocked ?candidate . })")) {
				TupleQuery query = connection.prepareTupleQuery("""
						PREFIX ex: <urn:factorized-exists:>
						SELECT ?root ?candidate WHERE {
						  ?root a ex:Root ; ex:candidate ?candidate ; ex:repeat ?repeat .
						  %s
						}
						""".formatted(filter));
				TupleExpr tupleExpr = ((SailTupleQuery) query).getParsedQuery().getTupleExpr().clone();
				FactorizedSolutionBagFingerprint enumerated;
				try (TupleQueryResult result = query.evaluate()) {
					enumerated = new FactorizedSolutionBagFingerprint(result.getBindingNames());
					while (result.hasNext()) {
						enumerated.add(result.next());
					}
				}
				List<String> bindingNames = tupleExpr.getBindingNames()
						.stream()
						.filter(bindingName -> !bindingName.startsWith("_const_"))
						.toList();

				FactorizedTupleExprEvaluator.Evaluation factorized = new FactorizedTupleExprEvaluator(connection,
						bindingNames).evaluate(tupleExpr);

				assertEquals(enumerated.fingerprint(), factorized.fingerprint(), filter);
				assertEquals(filter.startsWith("FILTER NOT") ? 4L : 2L,
						factorized.fingerprint().rowCount(), filter);
			}
		} finally {
			repository.shutDown();
		}
	}

